order = []


def C(*keys):
    """Ссылка на источники. Номер присваивается при первом упоминании."""
    for key in keys:
        if key not in order:
            order.append(key)
    numbers = sorted(order.index(k) + 1 for k in keys)
    return "[" + ", ".join(map(str, numbers)) + "]"


def src(path, *names):
    """Исходный код функций или классов верхнего уровня."""
    text = Path(path).read_text(encoding="utf-8")
    parts = []
    for node in ast.parse(text).body:
        if isinstance(node, (ast.FunctionDef, ast.ClassDef)) and node.name in names:
            parts.append(ast.get_source_segment(text, node))
    assert len(parts) == len(names), names
    return "\n\n".join(parts)


def log(name):
    return (CHECK / name).read_text(encoding="utf-8").strip()


def cell(notebook, name, caption):
    code, out = nb.cell(notebook, name)
    return caption, code, out or None


