def nbsp(text):
    """Неразрывный пробел внутри чисел: 5 972, 1 231."""
    return re.sub(r"(?<=\d) (?=\d{3}\b)", "\u00a0", whole_words(text))


def whole_words(text):
    """Дефис внутри слова не разрывается на границе строки; адреса сайтов остаются как есть."""
    return re.sub(r"\S+", lambda m: m.group(0) if "://" in m.group(0)
                  else re.sub(r"(?<=\w)-(?=\w)", "\u2011", m.group(0)), text)


def apply_no_break_hyphens(document):
    """Заменяет метку U+2011 на штатный неразрывный дефис Word, чтобы шрифт не менялся."""
    for t in list(document.element.body.iter(qn("w:t"))):
        if not t.text or "\u2011" not in t.text:
            continue
        run = t.getparent()
        position = run.index(t)
        run.remove(t)
        for i, part in enumerate(t.text.split("\u2011")):
            if i:
                run.insert(position, OxmlElement("w:noBreakHyphen"))
                position += 1
            if part:
                piece = OxmlElement("w:t")
                piece.text = part
                piece.set(qn("xml:space"), "preserve")
                run.insert(position, piece)
                position += 1


class NoteDoc(VkrDocument):
    def para(self, text, blue=False):
        """Новая мысль начинается с нового абзаца: граница отмечена в тексте знаком ||."""
        for part in text.split("||"):
            paragraph = super().para(nbsp(part), blue=False)
        return paragraph

    def _add_page_numbers(self, section=None):
        if section is not None:
            super()._add_page_numbers(section)

    def table(self, caption, header, rows, widths_cm=None, font_size=12):
        t = super().table(caption, header, rows, widths_cm, font_size)
        for c in t.rows[0].cells:              # шапка таблицы: светло-серая заливка и жирный шрифт
            shading = OxmlElement("w:shd")
            shading.set(qn("w:val"), "clear")
            shading.set(qn("w:color"), "auto")
            shading.set(qn("w:fill"), "D9D9D9")
            c._tc.get_or_add_tcPr().append(shading)
            for q in c.paragraphs:
                for r in q.runs:
                    r.font.bold = True
        for i, row in enumerate(t.rows):       # таблица не разрывается между страницами
            row._tr.get_or_add_trPr().append(OxmlElement("w:cantSplit"))
            if i < len(t.rows) - 1:
                for c in row.cells:
                    for p in c.paragraphs:
                        p.paragraph_format.keep_with_next = True
        return t

    def appendix_heading(self, letter, title):
        p = self.doc.add_paragraph(style="Heading 1")
        p.paragraph_format.page_break_before = True
        p.add_run(f"Приложение {letter}").add_break()
        p.add_run(title)


