def plain(text, size=14, bold=False, align=WD_ALIGN_PARAGRAPH.CENTER, spacing=WD_LINE_SPACING.SINGLE):
    p = doc.add_paragraph()
    p.paragraph_format.first_line_indent = Cm(0)
    p.paragraph_format.alignment = align
    p.paragraph_format.line_spacing_rule = spacing
    _set_font(p.add_run(text), size=size, bold=bold)
    return p


